/* Hands-on mode replaces quiz interactions while retaining the RPG map. */
const S=CMP_SIM,PRACTICAL_KEY='cmp-fab-practical-v1';
let selectedRun=1,selectedMeter='M1',benchTab='recipe',comparisonResult=null,compareSel=[null,null];
try{const raw=JSON.parse(localStorage.getItem(PRACTICAL_KEY)||'null');game=raw?.sim?.version===1?E.normalize(raw):E.fresh()}catch(e){game=E.fresh()}
if(!game.sim)game.sim=S.init(game.day,E.caseIndex(game));
selectedRun=game.sim.runs.at(-1)?.id||1;
E.stations.find(s=>s.id==='tool').short=T('参数 / 耗材','パラメータ / 消耗品');E.stations.find(s=>s.id==='lab').short=T('加工试片','ウェーハ処理');E.stations.find(s=>s.id==='desk').short=T('对照分析','比較分析');E.stations.find(s=>s.id==='metrology').short=T('量测结果','測定結果');
const scenario=()=>{const d=S.describe(game.sim);if(!shift().report){d.title=T(`Day ${game.day} 的案例`,`Day ${game.day} の案件`);d.brief=d.task}return d},eventNotice=()=>{const n=game.sim.event?.notice;if(!n)return '';delete game.sim.event.notice;return ' ⚠ '+n},runs=()=>game.sim.runs,measured=()=>runs().filter(r=>r.measurements.length),runSelected=()=>runs().find(r=>r.id===selectedRun)||runs().at(-1);
save=function(){try{localStorage.setItem(PRACTICAL_KEY,JSON.stringify(game))}catch(e){saveWorks=false}if($('saveNote'))$('saveNote').textContent=saveWorks?T('实验与进度自动保存在当前浏览器。','実験と進行状況はこのブラウザに自動保存されます。'):T('当前无法保存；请暂时不要关闭页面。','現在保存できません。しばらくページを閉じないでください。')};
objectives=function(){const s=shift();return [{label:T('接班领取任务','引き継ぎ・課題受領'),done:s.briefed,to:'lead'},{label:T('运行基准试片','ベースライン処理'),done:runs().length>0,to:'tool'},{label:T('量测观察结果','測定して結果を確認'),done:measured().length>0,to:'metrology'},{label:T('干预与对照实验','介入と比較実験'),done:game.sim.compared.length>0,to:'lab'},{label:T('提交实验报告','実験報告書の提出'),done:s.report,to:'desk'},{label:T('打卡 · 下一场','退勤 · 次のシナリオ'),done:s.clocked,to:'exit'}]};
nextTask=function(){return objectives().find(t=>!t.done)||objectives().at(-1)};
hud=function(){const s=shift();$('week').textContent=T('自主实验','自主実験');$('day').textContent='DAY '+String(game.day).padStart(2,'0');$('clock').textContent=E.time(game);$('period').textContent=s.minute>=1050?T('加班中','残業中'):s.minute>=780?T('午后','午後'):T('早班','午前');$('energyText').textContent=s.energy+' / 100';$('energyBar').style.width=s.energy+'%';$('energyMeter').setAttribute('aria-valuenow',s.energy);$('rank').textContent=E.rank(game);$('xp').textContent=game.xp;$('missionTitle').textContent=scenario().title;$('missionBrief').textContent=scenario().brief;const ts=objectives(),next=ts.findIndex(t=>!t.done);$('tasks').innerHTML=ts.map((t,i)=>`<button class="task ${t.done?'complete':''} ${i===next?'current':''}" data-go="${t.to}"><span>${t.done?'✓':i+1}</span>${t.label}</button>`).join('');$('nextHint').textContent=s.clocked?T('本次实验已归档。可查看总结，或进入下一场。','今回の実験は保管済みです。まとめを確認するか、次のシナリオへ進めます。'):s.energy<15?T('先去休息角恢复专注力。实验次数没有硬性上限。','まず休憩コーナーで集中力を回復しましょう。実験回数に厳密な上限はありません。'):s.report?T('报告已提交。到出口打卡，进入下一个场景。','報告書は提出済みです。出口で退勤して、次のシナリオへ進みましょう。'):s.energy<S.FOCUS?T(`⚠ 专注力低于 ${S.FOCUS}：加工和量测时可能出现操作失误（参数输错一格、用错量测设备）。失误不会提示，只会留在记录里。`,`⚠ 集中力が ${S.FOCUS} 未満です：処理や測定で操作ミス（パラメータの 1 目盛りずれ、測定機の取り違え）が起こることがあります。ミスは通知されず、記録にだけ残ります。`):!s.briefed?T('先接班。然后你可以自由调参数、换耗材、加工和量测。','まず引き継ぎを受けましょう。その後はパラメータ調整、消耗品交換、処理、測定を自由に行えます。'):!runs().length?T('建议先保持原状跑 1 片，记录基准，再动参数或耗材。','まず現状のまま 1 枚処理してベースラインを記録し、その後でパラメータや消耗品を変えるのがおすすめです。'):!measured().length?T('试片已经加工完成。去量测室选择 M1 或 M2 读出数据。','テストウェーハの処理が完了しました。測定室で M1 か M2 を選んでデータを読み取りましょう。'):T('用实验记录做前后对照。同一片可以跨设备复测；多个新试片可以验证重复性。','実験記録で前後比較をしましょう。同じウェーハは別の測定機で再測定でき、新しいテストウェーハを複数処理すれば繰り返し性を確認できます。');$('relations').innerHTML=`<div class="costSummary"><span>${T('试片','テストウェーハ')} <b>${runs().length}</b></span><span>${T('已量测','測定済み')} <b>${measured().length}</b></span><span>${T('模拟成本','模擬コスト')} <b>${game.sim.expense}</b></span></div>`;document.querySelector('.coworkers h2').textContent=T('今日实验资源','本日の実験リソース');$('latestLog').textContent=s.log.length?s.log.at(-1).at+'　'+s.log.at(-1).text:T('08:30　今天由你决定做什么实验。','08:30　今日どんな実験をするかは、あなたが決めます。');$('intro').hidden=s.briefed||!briefIntro;const nextId=nextTask().to;$('stations').innerHTML=E.stations.map(st=>`<button class="station" data-go="${st.id}" style="left:${st.x}%;top:${st.id==='exit'?st.y:st.y+(st.y<50?-2:2)}%" aria-label="${T(`前往${st.name}`,`${st.name}へ移動`)}">${st.id===nextId?'<span class="questdot">!</span>':''}${st.icon} ${st.short}</button>`).join('');updatePosition();save();};
function targets(){return `<div class="targetBand"><b>${T('本关试片目标','今回のテストウェーハ目標')}</b><span>膜厚 185–215 nm</span><span>${T('去除非均匀度','面内不均一性')} ≤5%</span><span>${T('缺陷 ≤15 个/片','欠陥 ≤15 個/枚')}</span></div>`}
function practicalNotes(){return `<h3>${T('实验假设与计划','実験の仮説と計画')}</h3><textarea id="simHypothesis" ${shift().report?'readonly':''} placeholder="${T('我要只改变……，保持……不变。若假设成立，预计……。','……だけを変え、……は固定する。仮説が正しければ、……となるはず。')}">${esc(game.sim.hypothesis)}</textarea><h3>${T('观察笔记','観察メモ')}</h3><textarea id="simNotes" ${shift().report?'readonly':''} placeholder="${T('记录你看到的差异，以及下一步要验证什么。','気づいた差と、次に検証したいことを記録しましょう。')}">${esc(game.sim.note)}</textarea><p class="small">${T('自由文字不由关键词打分。实验习惯分来自你实际留下的记录，不等于根因已经被证明。','自由記述はキーワードで採点されません。実験習慣スコアは実際に残した記録に基づくもので、真因が証明されたことを意味するわけではありません。')}</p>`}
function toolTabs(){return `<div class="simTabs"><button data-stab="recipe" class="${benchTab==='recipe'?'selected':''}">${T('调参数','パラメータ調整')}</button><button data-stab="service" class="${benchTab==='service'?'selected':''}">${T('耗材与校准','消耗品と校正')}</button><button data-stab="feedback" class="${benchTab==='feedback'?'selected':''}">${T('实际反馈','実測値')}</button><button data-stab="doe" class="${benchTab==='doe'?'selected':''}">${T('自定义 2×2 DOE','カスタム 2×2 DOE')}</button></div>`}
function equipmentPicker(){return `<div class="rowActions"><label for="simTool">${T('当前机台','現在の号機')}</label><select id="simTool" class="simSelect" ${shift().report?'disabled':''}><option value="A" ${game.sim.tool==='A'?'selected':''}>Tool A</option><option value="B" ${game.sim.tool==='B'?'selected':''}>Tool B</option></select><span class="small">${T('两台机台分别保存配方与耗材状态。','2 台の号機は、それぞれレシピと消耗品の状態を個別に保持します。')}</span></div>`}
function machineDiagram(){const t=S.active(game);return `<div class="hardware" id="machineStatus"><svg viewBox="0 0 280 220" role="img" aria-label="${T('简化俯视图：大圆为研磨垫，小圆为晶圆，箭头表示旋转方向','簡略上面図：大きい円が研磨パッド、小さい円がウェーハ、矢印は回転方向')}"><g class="platen"><circle cx="140" cy="105" r="86" fill="${t.pad.type==='hard'?'#4d687f':'#977b52'}" stroke="#bed3cc" stroke-width="4"/><circle cx="140" cy="105" r="67" fill="none" stroke="#d1c5a7" stroke-width="2" stroke-dasharray="3 6"/><path d="M140 20v170M55 105h170" stroke="#c7b991" stroke-width="2"/></g><circle cx="163" cy="96" r="39" fill="#65b5c6" fill-opacity=".92" stroke="#d7f0eb" stroke-width="3"/><text x="163" y="100" fill="#102d3b" text-anchor="middle" font-size="13">${T('晶圆','ウェーハ')}</text><text x="140" y="212" fill="#bed7d5" text-anchor="middle" font-size="12">${T('研磨垫 · 俯视示意（非比例）','研磨パッド · 上面イメージ（縮尺なし）')}</text></svg><div class="statusLine"><span>${T('研磨垫','研磨パッド')}</span><b>${t.pad.type==='hard'?T('较硬型','硬質タイプ'):T('标准型','標準タイプ')} · ${t.pad.serial}</b></div><div class="statusLine"><span>使用量</span><b>${Math.round(t.pad.age)} ${T('片','枚')}</b></div><div class="statusLine"><span>${T('保持环','リテーナリング')}</span><b>${t.ring.serial}</b></div><div class="statusLine"><span>${T('研磨液','スラリー')}</span><b>${t.slurry}</b></div><p class="small">${T('结果在加工、量测之后揭晓。界面不预先显示模型答案。','結果は処理と測定の後に分かります。画面にモデルの答えが先に表示されることはありません。')}</p><span class="runningText">${T('正在完成模拟研磨…','模擬研磨を実行中…')}</span></div>`}
function runButtons(){return `${shift().briefed?'':`<div class="notice">${T('还没有接班，所以不能加工。先去晨会找林前辈领取今天的任务。','まだ引き継ぎを受けていないため、処理できません。まず朝会で林先輩から今日の課題を受け取ってください。')} <button data-go="lead">${T('去晨会','朝会へ')}</button></div>`}<div class="runControls"><button class="primary" data-sim="run" data-count="1" ${!shift().briefed||shift().report?'disabled':''}>${T('▶ 加工 1 片','▶ 1 枚処理')}</button><button data-sim="run" data-count="3" ${!shift().briefed||shift().report?'disabled':''}>${T('重复加工 3 片','3 枚繰り返し処理')}</button><button data-sim="run" data-count="5" ${!shift().briefed||shift().report?'disabled':''}>${T('重复加工 5 片','5 枚繰り返し処理')}</button></div><p class="small">${T('每片都是相同入片膜厚 500 nm 的新工程试片，自动记录完整参数、耗材和时间。加工后去量测室读数。','どれも初期膜厚 500 nm の新しいテストウェーハで、パラメータ・消耗品・時刻がすべて自動記録されます。処理後は測定室で値を読み取りましょう。')}</p>`}
function recipePanel(){const p=game.sim.recipes[game.sim.tool];return `${equipmentPicker()}${targets()}<div class="bench"><div>${Object.entries(S.bounds).map(([key,[lo,hi,step,name,unit]])=>`<div class="knob"><label for="range-${key}">${name} <span class="small">${unit}</span></label><input class="num" id="num-${key}" data-param="${key}" type="number" min="${lo}" max="${hi}" step="${step}" value="${p[key]}" aria-label="${T(`${name}数值`,`${name}の数値`)}" ${shift().report?'disabled':''}><input id="range-${key}" type="range" data-param="${key}" min="${lo}" max="${hi}" step="${step}" value="${p[key]}" ${shift().report?'disabled':''}><small>${T('教学范围','学習用範囲')} ${lo}–${hi} ${unit}</small></div>`).join('')}${runButtons()}<button data-sim="resetRecipe" ${shift().report?'disabled':''}>${T('恢复本场初始配方（不恢复耗材）','今回の初期レシピに戻す（消耗品は戻りません）')}</button><p class="liveFeedback" id="paramFeedback">${T('调整参数本身不计实验，点击加工才会产生新数据。','パラメータを調整するだけでは実験になりません。処理を実行して初めて新しいデータが生まれます。')}</p></div>${machineDiagram()}</div>`}
function servicePanel(){const t=S.active(game),lock=shift().report?'disabled':'';return `${equipmentPicker()}<p>${T('更换的“盘子”在这里具体分成研磨垫（Pad）、保持环（Retaining Ring）。换新垫后可以选择先磨合，也可以直接跑试片观察差别。','交換できる部品は、ここでは研磨パッド（Pad）とリテーナリング（Retaining Ring）に分かれます。新しいパッドに交換した後は、先に慣らしを行うことも、そのままテストウェーハを処理して違いを観察することもできます。')}</p><div class="serviceGrid"><section class="section"><h3>${T('研磨垫','研磨パッド')} · ${t.pad.serial}</h3><p class="small">${T('当前','現在')} ${t.pad.type==='hard'?T('较硬型','硬質タイプ'):T('标准型','標準タイプ')}${T('，累计','、累計')} ${Math.round(t.pad.age)} ${T('片。','枚。')}</p><label for="padType">${T('新垫类型','新しいパッドの種類')}</label><select id="padType"><option value="standard">${T('标准型','標準タイプ')}</option><option value="hard">${T('较硬型','硬質タイプ')}</option></select><div class="rowActions"><button data-sim="service" data-service="pad" ${lock}>${T('更换研磨垫','研磨パッド交換')}</button></div><p class="small">${T('45 min · 专注力 −8 · 成本 600','45 min · 集中力 −8 · コスト 600')}</p></section><section class="section"><h3>${T('修整 / 磨合','ドレッシング / 慣らし')}</h3><p class="small">${T('作用于当前研磨垫，记录累计修整时间。','現在の研磨パッドに作用し、累計ドレッシング時間が記録されます。')}</p><select id="conditionSeconds" aria-label="${T('修整时长','ドレッシング時間')}"><option value="30">30 秒</option><option value="60" selected>60 秒</option><option value="120">120 秒</option></select><div class="rowActions"><button data-sim="service" data-service="condition" ${lock}>${T('执行修整','ドレッシング実行')}</button></div><p class="small">${T('准备工时 10 min · −4 · 成本 20','準備時間 10 min · −4 · コスト 20')}</p></section><section class="section"><h3>${T('保持环','リテーナリング')} · ${t.ring.serial}</h3><p class="small">${T(`累计 ${t.ring.age} 片。更换不会改变研磨垫。`,`累計 ${t.ring.age} 枚。交換しても研磨パッドは変わりません。`)}</p><button data-sim="service" data-service="ring" ${lock}>${T('更换保持环','リテーナリング交換')}</button><p class="small">${T('30 min · −6 · 成本 350','30 min · −6 · コスト 350')}</p></section><section class="section"><h3>${T('研磨液批次','スラリーロット')}</h3><select id="slurryLot" aria-label="${T('研磨液批次','スラリーロット')}"><option value="L1" ${t.slurry==='L1'?'selected':''}>L1</option><option value="L2" ${t.slurry==='L2'?'selected':''}>L2</option></select><div class="rowActions"><button data-sim="service" data-service="slurry" ${lock}>${T('切换批次','ロット切替')}</button></div><p class="small">${T('10 min · −3 · 成本 120','10 min · −3 · コスト 120')}</p></section><section class="section"><h3>${T('实际流量','実流量')}</h3><p class="small">${T('校准比例关系，不改变配方流量设定。','比例関係を校正します。レシピの流量設定値は変わりません。')}</p><button data-sim="service" data-service="flow" ${lock}>${T('执行流量校准','流量校正を実行')}</button><p class="small">${T('20 min · −5 · 成本 80','20 min · −5 · コスト 80')}</p></section><section class="section"><h3>${T('实际压力','実圧力')}</h3><p class="small">${T('校准设定与实际压力的对应关系。','設定値と実圧力の対応関係を校正します。')}</p><button data-sim="service" data-service="pressure" ${lock}>${T('执行压力校准','圧力校正を実行')}</button><p class="small">${T('20 min · −5 · 成本 80','20 min · −5 · コスト 80')}</p></section></div><h3>${T('维护记录','メンテナンス記録')}</h3>${game.sim.services.length?game.sim.services.map(s=>`<div class="logEntry"><time>${s.at}</time><span>Tool ${s.tool} · ${s.label} ${s.arg||''}</span></div>`).join(''):`<p class="small">${T('尚未维护。原始状态仍可用于基准实验。','まだメンテナンスしていません。元の状態のままベースライン実験に使えます。')}</p>`}`}
function feedbackPanel(){return `${equipmentPicker()}<p>${T('这里读取实际传感反馈和耗材检查结果。它们与设定值是两套信息。','ここではセンサーの実測値と消耗品の点検結果を確認します。これらは設定値とは別の情報です。')}</p><button class="primary" data-sim="inspect" ${shift().report?'disabled':''}>${T('检查当前状态 · 10 min / −3','現在の状態を点検 · 10 min / −3')}</button>${game.sim.checks.map(c=>`<section class="section"><h3>${c.at} · Tool ${c.tool}</h3><div class="tableWrap"><table><thead><tr><th>${T('项目','項目')}</th><th>${T('设定','設定値')}</th><th>${T('实际反馈','実測値')}</th></tr></thead><tbody><tr><td>${T('压力 psi','圧力 psi')}</td><td>${c.recipe.pressure}</td><td>${c.actual.pressure}</td></tr><tr><td>流量 mL/min</td><td>${c.recipe.flow}</td><td>${c.actual.flow}</td></tr><tr><td>温度 °C</td><td>${c.recipe.temp}</td><td>${c.actual.temp}</td></tr></tbody></table></div><p class="small">${T(`Pad ${Math.round(c.padAge)} 片；保持环 ${c.ringAge} 片；保持环磨损观察指数 ${c.ring}（0–1，仅本模型）。`,`Pad ${Math.round(c.padAge)} 枚、リテーナリング ${c.ringAge} 枚、リテーナリング摩耗観察指数 ${c.ring}（0–1、本モデル限定）。`)}</p><p>${c.surface}</p></section>`).reverse().join('')}`}
function doePanel(){const opts=(selected)=>Object.entries(S.bounds).map(([k,v])=>`<option value="${k}" ${k===selected?'selected':''}>${v[3]} (${v[4]})</option>`).join('');return `${equipmentPicker()}<p>${T('自己指定两个因素及低、高水平。系统将四个组合随机排列运行，其他配方保持当前值。每个组合可以重复 1–3 片。','2 つの因子と、それぞれの低水準・高水準を自分で指定します。4 つの組み合わせはランダムな順序で実行され、その他のレシピは現在値のままです。各組み合わせは 1–3 枚繰り返せます。')}</p><div class="doeGrid"><span>${T('因素','因子')}</span><span>${T('低水平','低水準')}</span><span>${T('高水平','高水準')}</span><select id="doeA" aria-label="${T('因素 A','因子 A')}">${opts('temp')}</select><input id="doeAL" aria-label="${T('因素 A 低水平','因子 A 低水準')}" type="number" value="23" step="any"><input id="doeAH" aria-label="${T('因素 A 高水平','因子 A 高水準')}" type="number" value="27" step="any"><select id="doeB" aria-label="${T('因素 B','因子 B')}">${opts('flow')}</select><input id="doeBL" aria-label="${T('因素 B 低水平','因子 B 低水準')}" type="number" value="150" step="any"><input id="doeBH" aria-label="${T('因素 B 高水平','因子 B 高水準')}" type="number" value="200" step="any"></div><label for="doeReps">${T('每个组合的重复数','各組み合わせの繰り返し数')}</label><select id="doeReps" class="simSelect"><option value="1">${T('1 片 · 共 4 片','1 枚 · 計 4 枚')}</option><option value="2">${T('2 片 · 共 8 片','2 枚 · 計 8 枚')}</option><option value="3">${T('3 片 · 共 12 片','3 枚 · 計 12 枚')}</option></select><div class="rowActions"><button class="primary" data-sim="doe" ${!shift().briefed||shift().report?'disabled':''}>${T('执行我设计的 2×2 实验','設計した 2×2 実験を実行')}</button></div><p class="small">${T('运行结束恢复当前配方。耗材使用量继续累计；随机顺序有助于减小时间漂移的影响。请注意参数单位与允许步长。','実行後は現在のレシピに戻ります。消耗品の使用量は累積され続けます。ランダムな順序は時間ドリフトの影響を小さくするのに役立ちます。パラメータの単位と設定可能な刻み幅にご注意ください。')}</p>${doeResults()}`}
function doeResults(){const batches=[...new Set(runs().filter(r=>r.doe).map(r=>r.doe.batch))];return batches.map(batch=>{const set=runs().filter(r=>r.doe?.batch===batch),d=set[0].doe,groups=[];for(const a of[d.lowA,d.highA])for(const b of[d.lowB,d.highB]){const rr=set.filter(r=>r.snapshot.recipe[d.a]===a&&r.snapshot.recipe[d.b]===b),mm=rr.map(r=>S.latest(r)).filter(Boolean),mean=k=>mm.length?+(mm.reduce((n,m)=>n+m.metrics[k],0)/mm.length).toFixed(2):null;groups.push({a,b,n:mm.length,planned:rr.length,th:mean('thickness'),def:mean('defects'),meters:mm.map(m=>m.meter+'-'+m.epoch)});}const complete=groups.every(g=>g.n===g.planned),same=new Set(groups.flatMap(g=>g.meters)).size===1,delta=complete&&same?(groups[3].def-groups[1].def)-(groups[2].def-groups[0].def):null;return `<section class="section"><h3>${batch} · ${S.bounds[d.a][3]} × ${S.bounds[d.b][3]}</h3><div class="tableWrap"><table><thead><tr><th>A</th><th>B</th><th>${T('已量测/计划','測定済み/計画')}</th><th>${T('均值膜厚 nm','平均膜厚 nm')}</th><th>${T('均值缺陷','平均欠陥数')}</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${g.a}</td><td>${g.b}</td><td>${g.n}/${g.planned}</td><td>${g.th??'—'}</td><td>${g.def??'—'}</td></tr>`).join('')}</tbody></table></div><p class="small">${delta===null?T('量测完全部组合，且使用同一量测设备及校准版本后，显示交互差值。','すべての組み合わせを、同じ測定機・同じ校正バージョンで測定し終えると、交互作用の差分が表示されます。'):T(`缺陷的差中之差 ΔΔ = ${delta.toFixed(2)} 个/片（A 的效应在 B 高水平与低水平之间的差）。这是描述性对照；样本波动与机理仍需判断。`,`欠陥の差の差 ΔΔ = ${delta.toFixed(2)} 個/枚（B の高水準と低水準での A の効果の差）。これは記述的な比較であり、サンプルのばらつきとメカニズムは別途判断が必要です。`)}</p></section>`}).join('')}
/* 试片的规律化命名：#编号 · 机台 · 方案标签 · 结果。
   方案标签 = 第一片叫“基准/首片”；与更早某片配置完全相同的叫“同 #k”；其余写出相对第一片改了什么（如“修整 120s”“压力 3.2”）。 */
function runTag(r){const first=runs()[0],fp=x=>JSON.stringify(x.snapshot.fingerprint);if(r.id===first.id)return r.baseline?T('基准','ベースライン'):T('首片','1 枚目');const twin=runs().find(x=>x.id<r.id&&fp(x)===fp(r));if(twin)return twin.id===first.id?T(`同 #${twin.id}（${first.baseline?'基准':'首片'}条件）`,`#${twin.id} と同条件`):T(`同 #${twin.id}`,`#${twin.id} と同条件`);const f=r.snapshot.fingerprint,keys=S.diff(first,r).filter(k=>k!=='tool'&&!(k==='padType'&&f.padType==='standard')),name={pad:T('换垫','パッド交換'),padType:T('较硬垫','硬質パッド'),ring:T('换环','リング交換'),flowCalibration:T('流量校准','流量校正'),pressureCalibration:T('压力校准','圧力校正')},parts=keys.map(k=>S.bounds[k]?S.bounds[k][3]+' '+f[k]:k==='conditioning'?T(`修整 ${f.conditioning}s`,`ドレッシング ${f.conditioning}s`):k==='slurry'?T('研磨液 ','スラリー ')+f.slurry:name[k]||k);if(!parts.length)return T('仅机台不同','号機のみ異なる');return parts.slice(0,3).join(' + ')+(parts.length>3?' +'+(parts.length-3):'')}
function runLabel(r){const m=S.latest(r);return `#${r.id} · Tool ${r.snapshot.tool} · ${runTag(r)}${r.doe?' · DOE':''}${m?(S.pass(m)?' ✓':' ✗'):''}`}
function pairHistory(){const rows=game.sim.compared.map(k=>{const [a,b]=k.split('-').map(Number),ra=runs().find(r=>r.id===a),rb=runs().find(r=>r.id===b);if(!ra||!rb||!S.latest(ra)||!S.latest(rb))return '';const n=S.diff(ra,rb).length,mix=S.latest(ra).meter!==S.latest(rb).meter;return `<div class="logEntry"><span>${esc(runLabel(ra))} ↔ ${esc(runLabel(rb))}<br><b>${n===1&&!mix?T('✓ 单变量对照','✓ 一因子比較'):n===0?T('重复片对照','繰り返しの比較'):T(`差 ${n} 个因素`,`因子の差 ${n} 個`)}${mix?T(' · 量测设备不同',' · 測定機が異なる'):''}</b></span><button data-sim="compareView" data-a="${a}" data-b="${b}">${T('查看','表示')}</button></div>`}).join('');return rows?`<h3>${T('已建立的对照','作成済みの比較')}</h3>${rows}`:''}
function trialPicker(id='trialSelect'){return `<select id="${id}" class="simSelect" aria-label="${T('选择试片','テストウェーハを選択')}">${runs().map(r=>`<option value="${r.id}" ${selectedRun===r.id?'selected':''}>${esc(runLabel(r))}${r.measurements.length?'':T(' · 未量测',' · 未測定')}</option>`).join('')}</select>`}
function colorThickness(v){const q=Math.max(0,Math.min(1,(v-150)/100));if(q<.5){const k=q*2;return `rgb(${Math.round(99+27*k)},${Math.round(168+56*k)},${Math.round(222-29*k)})`}const k=(q-.5)*2;return `rgb(${Math.round(126+117*k)},${Math.round(224-54*k)},${Math.round(193-80*k)})`}
function waferMap(m){return `<svg class="waferMap" viewBox="0 0 280 280" role="img" aria-label="${T(`49 个实测膜厚点，单位 nm。最小 ${m.metrics.min}，最大 ${m.metrics.max}。`,`実測膜厚 49 点、単位 nm。最小 ${m.metrics.min}、最大 ${m.metrics.max}。`)}"><circle cx="140" cy="140" r="129" fill="#163b4b" stroke="#a9c6ca" stroke-width="2"/>${m.points.map(p=>`<circle cx="${140+p.x*125}" cy="${140+p.y*125}" r="9" fill="${colorThickness(p.t)}"><title>${T(`点${p.id+1}：${p.t.toFixed(1)} nm`,`測定点 ${p.id+1}：${p.t.toFixed(1)} nm`)}</title></circle>`).join('')}<path d="M131 267h18" stroke="#d2dedb" stroke-width="4"/></svg>`}
function resultView(run){if(!run)return '';const own=S.latest(run,selectedMeter),m=own||S.latest(run),fallback=!own&&m?`<div class="notice">${T(`这片还没有用 ${selectedMeter} 量测过，下面显示的是 ${m.meter} 的读数。上方选好 ${selectedMeter} 后点「量测这片」，才会用 ${selectedMeter} 再测一次。`,`このウェーハはまだ ${selectedMeter} で測定されていません。下に表示されているのは ${m.meter} の読み値です。上で ${selectedMeter} を選んで「このウェーハを測定」を押すと、${selectedMeter} で測定されます。`)}</div>`:'';if(!m)return `<div class="notice">${T(`试片 #${run.id} 已加工，还没有量测结果。`,`テストウェーハ #${run.id} は処理済みですが、まだ測定結果がありません。`)}</div>`;const v=m.metrics;return `${targets()}${fallback}<h3>${T('试片','テストウェーハ')} #${run.id} · ${m.meter} / ${m.at}</h3><p class="measuredNote">${m.biasVerified?T('量测基准已核查','測定基準は確認済み'):T('此读数尚未做基准核查，可用参考片或 M2 对照','この読み値は基準確認がまだです。標準ウェーハまたは M2 で照合できます')} · ${T('49 测点','49 測定点')} · ${S.pass(m)?T('本次读数达标','今回の読み値は目標達成'):T('本次读数未全部达标','今回の読み値は一部目標未達')}</p><div class="resultMetrics"><div class="metricTile ${v.thickness<185||v.thickness>215?'fail':''}"><small>平均膜厚 nm</small><strong>${v.thickness}</strong></div><div class="metricTile"><small>${T('去除速率 nm/min','研磨レート nm/min')}</small><strong>${v.rr}</strong></div><div class="metricTile ${v.uniformity>5?'fail':''}"><small>${T('去除非均匀度 %','面内不均一性 %')}</small><strong>${v.uniformity}</strong></div><div class="metricTile ${v.defects>15?'fail':''}"><small>${T('缺陷 个/片','欠陥 個/枚')}</small><strong>${v.defects}</strong></div></div><div class="waferView"><div>${waferMap(m)}<div class="waferLegend"></div><div class="legendLabels"><span>≤150 nm</span><span>200</span><span>≥250 nm</span></div></div><div><h3>${T('晶圆膜厚分布','ウェーハ膜厚分布')}</h3><p>${T(`最薄 ${v.min} nm，最厚 ${v.max} nm。每个圆点对应一个量测位置。`,`最薄 ${v.min} nm、最厚 ${v.max} nm。各点が 1 つの測定位置に対応します。`)}</p><p class="small">${T('非均匀度 = 49 点去除厚度的标准差 ÷ 平均去除厚度 ×100%。去除速率 =（500 − 平均膜厚）÷ 实际研磨分钟数。','面内不均一性 = 49 点の除去量の標準偏差 ÷ 平均除去量 ×100%。研磨レート =（500 − 平均膜厚）÷ 実際の研磨時間（分）。')}</p><p class="small">${T('两者都由本次量测计算，量测偏差也会影响结果。缺陷采用同一缺陷检查模型，不随膜厚量测设备改变。','どちらも今回の測定値から計算されるため、測定の偏りも結果に影響します。欠陥は同一の欠陥検査モデルを用いており、膜厚測定機によって変わることはありません。')}</p></div></div><details><summary>${T('参数与耗材快照 / 所有量测','パラメータと消耗品のスナップショット / 全測定')}</summary>${snapshotTable(run)}<div class="tableWrap"><table><thead><tr><th>${T('设备/时间','測定機/時刻')}</th><th>膜厚 nm</th><th>RR</th><th>${T('非均匀度 %','面内不均一性 %')}</th></tr></thead><tbody>${run.measurements.map(mm=>`<tr><td>${mm.meter} / ${mm.at}</td><td>${mm.metrics.thickness}</td><td>${mm.metrics.rr}</td><td>${mm.metrics.uniformity}</td></tr>`).join('')}</tbody></table></div></details>`}
function snapshotTable(run){const s=run.snapshot;return `<div class="tableWrap"><table class="simTable"><tbody>${Object.entries(s.recipe).map(([k,v])=>`<tr><td>${S.bounds[k][3]} ${S.bounds[k][4]}</td><td>${v}</td></tr>`).join('')}<tr><td>${T('机台 / Pad / 使用量','号機 / Pad / 使用量')}</td><td>${s.tool} / ${s.pad.serial} / ${Math.round(s.pad.age)} ${T('片','枚')}</td></tr><tr><td>${T('Pad 类型 / 累计修整','Pad 種類 / 累計ドレッシング')}</td><td>${s.pad.type==='hard'?T('较硬型','硬質タイプ'):T('标准型','標準タイプ')} / ${s.pad.conditioning} s</td></tr><tr><td>${T('保持环 / 研磨液','リテーナリング / スラリー')}</td><td>${s.ring.serial} / ${s.slurry}</td></tr></tbody></table></div>`}
/* 量测系统核查：最近一次参考片结果用结果框显示并给出判读；更早的记录折叠。 */
function refSection(){const log=game.sim.referenceLog,last=log.at(-1),d=last?Math.round((last.M1-200)*10)/10:0,ok=last&&Math.abs(d)<=1,stale=last&&last.epoch!==undefined&&last.epoch!==game.sim.meterEpoch,line=r=>T(`${r.at} · 标准值 200 nm；M1 ${r.M1} nm；M2 ${r.M2} nm`,`${r.at} · 基準値 200 nm、M1 ${r.M1} nm、M2 ${r.M2} nm`);
return `<section class="section" id="refSection"><h3>${T('量测系统核查','測定システムの確認')}</h3><div class="rowActions"><button data-sim="reference" ${shift().report?'disabled':''}>${T('检查 200 nm 参考片 · 8 min / −2','200 nm 標準ウェーハを確認 · 8 min / −2')}</button><button data-sim="service" data-service="meter" ${shift().report?'disabled':''}>${T('校准 M1 · 20 min / −5 / 成本80','M1 を校正 · 20 min / −5 / コスト80')}</button></div>${last?`<div class="notice ${ok?'good':''}"><b>${line(last)}</b><br>${ok?T('M1 与标准值一致。用 M1 量测的读数视为已核查，可以计分。','M1 は基準値と一致しています。M1 の読み値は基準確認済みとして扱われ、採点の対象になります。'):T(`M1 比标准值${d<0?'低':'高'} ${Math.abs(d)} nm，存在系统偏差：用 M1 测到的膜厚都带着这个偏差，晶圆本身未必有问题。可以校准 M1 后重新量测，或改用 M2。`,`M1 は基準値より ${Math.abs(d)} nm ${d<0?'低く':'高く'}、系統的な偏りがあります。M1 で測った膜厚にはすべてこの偏りが含まれており、ウェーハ自体に問題があるとは限りません。M1 を校正して再測定するか、M2 を使ってください。`)}${stale?'<br>'+T('这条记录是校准之前的。校准后再检查一次参考片，可以确认 M1 已恢复。','この記録は校正前のものです。校正後にもう一度標準ウェーハを確認すると、M1 の回復を確かめられます。'):''}</div>`:`<p class="small">${T('还没有检查过参考片。只用 M1 且没有核查时，读数达标也不计分；M2 的读数不受影响。','まだ標準ウェーハを確認していません。M1 だけを使い確認もしていない場合、読み値が目標内でも加点されません。M2 の読み値は影響を受けません。')}</p>`}${game.sim.meterEpoch>0?`<p class="small">${T(`M1 已校准 ${game.sim.meterEpoch} 次。校准前的 M1 读数不会自动修正，需要重新量测。`,`M1 は ${game.sim.meterEpoch} 回校正済みです。校正前の M1 の読み値は自動では修正されないため、再測定が必要です。`)}</p>`:''}${log.length>1?`<details><summary>${T('更早的参考片记录','過去の標準ウェーハ記録')}</summary>${log.slice(0,-1).reverse().map(r=>'<p class="small">'+line(r)+'</p>').join('')}</details>`:''}</section>`}
function metrologyPanel(){const pending=runs().filter(r=>!r.measurements.length);return `<p>${T('选择已经加工的试片，再选择量测设备。同片复测不会重新研磨。','処理済みのテストウェーハを選び、次に測定機を選びます。同じウェーハを再測定しても、再研磨はされません。')}</p>${refSection()}${runs().length?`<div class="rowActions">${trialPicker()}<select id="meterSelect" class="simSelect" aria-label="${T('量测设备','測定機')}"><option ${selectedMeter==='M1'?'selected':''}>M1</option><option ${selectedMeter==='M2'?'selected':''}>M2</option></select><button class="primary" data-sim="measure" ${shift().report?'disabled':''}>${T('量测这片','このウェーハを測定')}</button><button data-sim="measurePending" ${!pending.length||shift().report?'disabled':''}>${T(`量测未测 ${pending.length} 片`,`未測定 ${pending.length} 枚を測定`)}</button></div><p class="small">${T('工时 4 + 每片 2 min；成本每片 5。批量只处理尚无量测的试片；跨设备复测用“量测这片”。','所要時間 4 + 1 枚あたり 2 min、コストは 1 枚あたり 5。一括測定は未測定のテストウェーハだけが対象です。別の測定機で再測定するときは「このウェーハを測定」を使います。')}</p>${resultView(runSelected())}`:`<div class="notice">${T('还没有试片。先去机台加工。','まだテストウェーハがありません。まず号機で処理しましょう。')}<button data-go="tool">${T('前往参数台','パラメータ台へ')}</button></div>`}`}
function trialsTable(){return `<div class="experimentTable"><table class="simTable"><thead><tr><th>${T('试片','ウェーハ')}</th><th>${T('机台','号機')}</th><th>P / rpm</th><th>流量 / 秒 / °C</th><th>膜厚</th><th>NU %</th><th>${T('缺陷','欠陥')}</th><th>${T('量测','測定')}</th><th>${T('记录','記録')}</th></tr></thead><tbody>${runs().map(r=>{const m=S.latest(r),p=r.snapshot.recipe;return `<tr class="${game.sim.finalId===r.id?'selected':''}"><td>#${r.id}${r.doe?' DOE':''}<br><small>${esc(runTag(r))}</small></td><td>${r.snapshot.tool}</td><td>${p.pressure} / ${p.speed}</td><td>${p.flow} / ${p.time} / ${p.temp}</td><td class="${m?(S.pass(m)?'pass':'fail'):''}">${m?m.metrics.thickness:'—'}</td><td>${m?m.metrics.uniformity:'—'}</td><td>${m?m.metrics.defects:'—'}</td><td>${m?m.meter:T('待测','未測定')}</td><td><button data-sim="viewRun" data-rid="${r.id}">${T('查看','表示')}</button></td></tr>`}).join('')}</tbody></table></div><p class="small">${T('P：psi；转速：rpm；流量：mL/min；时间：s；膜厚：nm。每行使用该片最新一次量测，原始记录保留在详情中。','P：psi、回転数：rpm、流量：mL/min、時間：s、膜厚：nm。各行はそのウェーハの最新の測定値を表示し、元の記録は詳細に残っています。')}</p>`}
function pairPanel(){const opts=(selected)=>measured().map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${esc(runLabel(r))}</option>`).join('');return `<h3>${T('选择两片做前后对照','2 枚を選んで前後比較')}</h3><div class="pairControls"><select id="compareA" class="simSelect" aria-label="${T('对照试片 A','比較ウェーハ A')}">${opts(measured().some(r=>r.id===compareSel[0])?compareSel[0]:measured()[0]?.id)}</select><span>${T('对比','対')}</span><select id="compareB" class="simSelect" aria-label="${T('对照试片 B','比較ウェーハ B')}">${opts(measured().some(r=>r.id===compareSel[1])?compareSel[1]:measured().at(-1)?.id)}</select><button data-sim="compare" ${measured().length<2?'disabled':''}>${T('建立对照','比較を作成')}</button></div>${comparisonResult||`<p class="small">${T('系统会列出你实际改变了哪些因素，再显示结果差异。多项一起变好，不能确定是谁起作用。','実際に変更した因子を一覧にしたうえで、結果の差を表示します。複数の因子を同時に変えて良くなった場合、どれが効いたのかは特定できません。')}</p>`}${pairHistory()}`}
function reportPanel(){return `<h3>${T('记录你的最终方案','最終案の記録')}</h3><label for="finalTrial">${T('以哪片的配方和耗材状态作为最终记录？','どのウェーハのレシピと消耗品の状態を最終記録にしますか？')}</label><select id="finalTrial" class="simSelect" ${shift().report?'disabled':''}><option value="">${T('请选择已量测试片','測定済みのテストウェーハを選択')}</option>${measured().map(r=>`<option value="${r.id}" ${game.sim.finalId===r.id?'selected':''}>${esc(runLabel(r))}</option>`).join('')}</select><textarea id="simConclusion" ${shift().report?'readonly':''} placeholder="${T('你改变了什么？哪些数据支持它？还有什么没排除？下一步如何防止再发生？','何を変えましたか？どのデータがそれを裏付けていますか？まだ排除できていないことは？再発防止のために次に何をしますか？')}">${esc(game.sim.conclusion)}</textarea><p class="small">${T('至少运行并量测 3 片后可提交。可以带着未解决的问题结案；评分会指出哪些实验记录还缺失，不要求猜中一个选项。','3 枚以上を処理・測定すると提出できます。未解決の問題を残したまま完了しても構いません。採点では不足している実験記録が示されるだけで、正解の選択肢を当てる必要はありません。')}</p><button class="primary" data-sim="submit" ${shift().report?'disabled':''}>${T('提交实验记录与复盘','実験記録と振り返りを提出')}</button>`}
function deskPanel(){return `${targets()}${runs().length?trialsTable():`<p class="notice">${T('实验记录为空，先去参数台运行基准试片。','実験記録が空です。まずパラメータ台でベースラインのテストウェーハを処理しましょう。')}</p>`}${pairPanel()}${doeResults()}${shift().report?'':pathReview(false)}${practicalNotes()}${shift().report?simReview():solutionHTML(false)+reportPanel()}`}
stationBody=function(id){if(id==='lead')return speech('lead',T('今天没有答案选项。你来决定改什么、换什么、跑几片，再用记录解释结果。建议先留一组不改任何条件的基准。','今日は答えの選択肢はありません。何を変え、何を交換し、何枚処理するかはあなたが決め、記録をもとに結果を説明してください。まずは条件を一切変えないベースラインを 1 組残しておくのがおすすめです。'))+`<h3>${scenario().title}</h3><p>${scenario().brief}</p>${targets()}${shift().briefed?`<div class="notice good">${T('任务已领取。你可以自由往返机台、量测室和工位。','課題を受領しました。号機、測定室、自席を自由に行き来できます。')}</div><button class="primary" data-go="tool">${T('去参数与耗材台','パラメータ・消耗品台へ')}</button>`:`<button class="primary" data-sim="brief">${T('接班，开始自主实验','引き継ぎを受けて自主実験を開始')}</button>`}<p class="modelNote">${T('这是简化数学模型，不是实际设备数字孪生。配方、耗材、随机波动和量测偏差共同决定结果；所有数字只用于本游戏。','これは簡略化した数理モデルであり、実機のデジタルツインではありません。レシピ、消耗品、ランダムなばらつき、測定の偏りが合わさって結果が決まります。数値はすべて本ゲーム内だけのものです。')}</p>`;
if(id==='tool'||id==='lab')return toolTabs()+(benchTab==='recipe'?recipePanel():benchTab==='service'?servicePanel():benchTab==='feedback'?feedbackPanel():doePanel());if(id==='metrology')return metrologyPanel();if(id==='desk')return deskPanel();if(id==='break')return `<h3>${T('休息一下，让思路慢下来','ひと休みして、頭を整理しましょう')}</h3><p>${T(`当前专注力 ${shift().energy}/100。恢复后，可以继续设计和执行实验。`,`現在の集中力 ${shift().energy}/100。回復したら、引き続き実験の設計と実行ができます。`)}</p><button class="primary" data-sim="rest" ${shift().report||shift().energy===100?'disabled':''}>${T(`休息 20 min · 恢复 ${S.restGain(game)}`,`休憩 20 min · 回復 ${S.restGain(game)}`)}</button><p class="small">${T(`专注力低于 ${S.FOCUS} 时，加工和量测可能出现操作失误，并如实留在记录里。每次休息的恢复量递减（35、30、25…最低 15），少跑无效实验比多休息更有用。`,`集中力が ${S.FOCUS} 未満になると、処理や測定で操作ミスが起こることがあり、そのまま記録に残ります。休憩の回復量は回を追うごとに減ります（35、30、25…最低 15）。休憩を増やすより、無駄な実験を減らすほうが効果的です。`)}</p><p class="small">${T('休息次数和试片数量没有硬上限。成本与时间会如实记录，避免因资源耗尽无法继续练习。','休憩回数とテストウェーハ枚数に厳密な上限はありません。リソース切れで練習を続けられなくなることはありませんが、コストと時間はそのまま記録されます。')}</p>`;if(id==='exit')return shift().report?`<h3>${T('实验记录已归档。','実験記録を保管しました。')}</h3><button class="primary" data-sim="clockout">${T('打卡下班','退勤する')}</button>`:`<h3>${T('先保存这次实验的结论','まず今回の実験の結論を保存しましょう')}</h3><p>${T('即使问题还没有完全解决，也可以在工位写清楚已知与未知后结案。','問題が完全に解決していなくても、自席で分かっていること・分かっていないことを整理して書けば完了できます。')}</p><button data-go="desk">${T('去工位整理记录','自席で記録を整理する')}</button>`;return '';};
/* 结案后逐项说明失分原因，用本场的实际记录说话。 */
function simLoss(){const sim=game.sim,ms=measured(),first=runs()[0],final=runs().find(r=>r.id===sim.finalId),fm=final&&S.latest(final),fp=r=>JSON.stringify(r.snapshot.fingerprint),same=final?ms.filter(r=>fp(r)===fp(final)):[],ver=same.filter(r=>S.latest(r).biasVerified),ok=ver.filter(r=>S.pass(S.latest(r))),ids=a=>a.map(r=>'#'+r.id).join('、')||T('无','なし');
const pairs=sim.compared.map(k=>{const [a,b]=k.split('-').map(Number),ra=runs().find(r=>r.id===a),rb=runs().find(r=>r.id===b),n=S.diff(ra,rb).length,mix=S.latest(ra).meter!==S.latest(rb).meter;return T(`#${a}–#${b}：差 ${n} 个因素${mix?'，且量测设备不同':''}`,`#${a}–#${b}：因子の差 ${n} 個${mix?'、測定機も異なる':''}`)}).join('；');
const x=fm?.metrics,fails=x?[[x.thickness<185||x.thickness>215,T(`膜厚 ${x.thickness} nm 不在 185–215`,`膜厚 ${x.thickness} nm が 185–215 の範囲外`)],[x.uniformity>5,T(`非均匀度 ${x.uniformity}% 超过 5%`,`面内不均一性 ${x.uniformity}% が 5% 超`)],[x.defects>15,T(`缺陷 ${x.defects} 超过 15`,`欠陥 ${x.defects} が 15 超`)]].filter(f=>f[0]).map(f=>f[1]):[];
return [!runs().some(r=>r.baseline)?T('在任务所说的问题机台上加工第一片之前，已经改过它的参数、耗材或校准，所以没有留下“原状”的基准。（量测室的操作和检查不影响基准。）','課題で指定された号機で 1 枚目を処理する前に、その号機のパラメータ・消耗品・校正を変更したため、「現状のまま」のベースラインが残っていません。（測定室での操作や点検はベースラインに影響しません。）'):T(`基准片 #${runs().find(r=>r.baseline).id} 加工了，但没有量测。`,`ベースライン #${runs().find(r=>r.baseline).id} は処理されましたが、測定されていません。`),
T(`只量测了 ${ms.length} 片，每片 5 分，3 片拿满。`,`測定は ${ms.length} 枚のみです。1 枚 5 点、3 枚で満点です。`),
sim.compared.length?T(`建立过的对照里，没有一组是“只差 1 个因素、且用同一台量测设备”的：${pairs}。`,`作成した比較の中に、「因子の差が 1 つだけ、かつ同じ測定機」のものがありません：${pairs}。`):T('没有在工位点过「建立对照」。只看表格不算，需要选两片建立一次对照；或者让同一片在 M1 和 M2 各测一次。','自席で「比較を作成」を実行していません。表を見るだけでは加点されません。2 枚を選んで比較を作成するか、同じウェーハを M1 と M2 の両方で測定してください。'),
T(`与最终试片 #${final?.id} 配置完全相同的已量测试片：${ids(same)}；其中读数已核查：${ids(ver)}；已核查且达标：${ids(ok)}。需要 3 片（2 片得一半）。“配置相同”包括参数、机台、垫和环的序列号、累计修整时间、研磨液批次、校准版本——中途修整、换桶或输错参数，都会让前后的试片不算同一方案。`,`最終ウェーハ #${final?.id} と条件が完全に同じ測定済みウェーハ：${ids(same)}、うち基準確認済み：${ids(ver)}、確認済みかつ目標達成：${ids(ok)}。3 枚必要です（2 枚で半分）。「同じ条件」には、パラメータ、号機、パッドとリングのシリアル、累計ドレッシング時間、スラリーロット、校正バージョンが含まれます。途中のドレッシング、ロット切替、誤入力があると、前後のウェーハは同じ条件とみなされません。`),
fails.length?T(`最终试片 #${final?.id} 的最新读数未达标：${fails.join('，')}。`,`最終ウェーハ #${final?.id} の最新の読み値が目標未達：${fails.join('、')}。`):T(`最终试片 #${final?.id} 的读数达标，但这次量测没有经过基准核查：它是用 M1 测的，而本场没有在量测前检查过 200 nm 参考片（或参考片显示 M1 有偏差、之后没有校准并重测）。改用 M2，或先检查参考片，就能拿到这 20 分。`,`最終ウェーハ #${final?.id} の読み値は目標を満たしていますが、この測定は基準確認を経ていません。M1 で測定されており、測定前に 200 nm 標準ウェーハを確認していない（または M1 の偏りが見つかった後、校正して再測定していない）ためです。M2 を使うか、先に標準ウェーハを確認すれば、この 20 点が得られます。`),
T('没有检查 200 nm 参考片，也没有让同一片在 M1 和 M2 各测一次。','200 nm 標準ウェーハを確認しておらず、同じウェーハを M1 と M2 の両方で測定してもいません。')]}
/* 本场参考解法。结案后直接展开；进行中折叠并提示剧透，看过会如实记在复盘里（不扣分）。 */
let solutionOpen=false;
function solutionHTML(done){const so=scenario().solution,rows=[[T('看到什么','何が見えるか'),so.see],[T('怎么定位','どう特定するか'),so.find],[T('标准处置','標準の対処'),so.fix],[T('常见误区','よくある落とし穴'),so.trap]];return `<details id="solutionBox" ${done||solutionOpen?'open':''}><summary>${done?T('本场参考解法','今回の参考解法'):T('卡住了？展开本场参考解法（剧透）','行き詰まったら：今回の参考解法を開く（ネタバレ）')}</summary>${done?'':`<p class="small">${T('里面直接写了原因和处置步骤。查看不扣分，但会在复盘里如实记一笔。建议先看上面的「实验路径点评」，它不剧透。','原因と対処手順がそのまま書かれています。見ても減点はありませんが、振り返りに記録されます。まず上の「実験の道筋の講評」を見るのがおすすめです（ネタバレなし）。')}</p>`}${rows.map(([k,v])=>`<p><b>${k}：</b>${v}</p>`).join('')}<p class="small">${T('得分步骤见「? 玩法」里的标准攻略。数值每场随机，文中为大致范围。','得点の手順は「? 遊び方」の標準の攻略手順を参照。数値は毎回ランダムで、本文は目安の範囲です。')}</p></details>`}
document.addEventListener('toggle',e=>{if(e.target.id!=='solutionBox')return;solutionOpen=e.target.open;if(e.target.open&&!shift().report&&!game.sim.peeked){game.sim.peeked=CMP_RPG.time(game);save()}},true);
/* 实验路径点评：按时间顺序看每一次“改了条件之后的第一片”，只用玩家自己量到的数据说话，不透露原因。
   离规格的距离 = 膜厚、非均匀度、缺陷各自超出规格的比例之和；片间波动约 ±5 nm，所以小于 8 nm 的变化按“没变”处理。 */
function pathReview(done){const ms=measured();if(!ms.length)return '';const dist=x=>Math.max(0,185-x.thickness,x.thickness-215)/15+Math.max(0,x.uniformity-5)/5+Math.max(0,x.defects-15)/15,names={...Object.fromEntries(Object.entries(S.bounds).map(([k,v])=>[k,v[3]])),pad:T('研磨垫','研磨パッド'),padType:T('垫类型','パッド種類'),conditioning:T('修整时间','ドレッシング時間'),ring:T('保持环','リテーナリング'),slurry:T('研磨液批次','スラリーロット'),flowCalibration:T('流量校准','流量校正'),pressureCalibration:T('压力校准','圧力校正')},fp=r=>JSON.stringify(r.snapshot.fingerprint),notes=[],steps=[];
 const firstChange=runs().find(r=>fp(r)!==fp(runs()[0])&&r.snapshot.tool===runs()[0].snapshot.tool),firstAt=firstChange?firstChange.at:'99:99',checked=game.sim.checks.some(c=>c.at<=firstAt),refEarly=game.sim.referenceLog.some(x=>x.at<=firstAt)||runs().some(r=>r.measurements.some(m=>m.meter==='M2'&&m.at<=firstAt));
 if(!runs().some(r=>r.baseline))notes.push(['bad',T('没有留下基准：第一片之前就动了条件，后面的改善没有可比的起点。','ベースラインがありません。1 枚目の前に条件を変えたため、その後の改善を比べる起点がありません。')]);
 if(firstChange&&!checked)notes.push(['warn',T('第一次改条件之前，没有看过机台的「实际反馈」。设定与实际是否一致、耗材表面如何，是最便宜的线索（10 分钟、不花钱），应当先看再动手。','最初に条件を変える前に、号機の「実測値」を確認していません。設定と実測の一致や消耗品の表面状態は最も安価な手がかり（10 分・コスト 0）なので、手を動かす前に確認すべきです。')]);
 if(firstChange&&!refEarly)notes.push(['warn',T('第一次改条件之前，没有核查过量测（参考片或 M2 复测）。如果读数本身不准，后面所有的判断都会被带偏。','最初に条件を変える前に、測定の確認（標準ウェーハまたは M2 再測定）をしていません。読み値自体がずれていると、その後の判断がすべて引きずられます。')]);
 for(const tool of ['A','B']){const seq=ms.filter(r=>r.snapshot.tool===tool);let prev=null;for(const r of seq){if(prev&&fp(prev)!==fp(r)){const keys=S.diff(prev,r),a=S.latest(prev),b=S.latest(r),da=dist(a.metrics),db=dist(b.metrics),dT=b.metrics.thickness-a.metrics.thickness,dN=b.metrics.uniformity-a.metrics.uniformity,dD=b.metrics.defects-a.metrics.defects,flat=Math.abs(dT)<8&&Math.abs(dN)<1&&Math.abs(dD)<5,mix=a.meter!==b.meter,epoch=a.meter==='M1'&&b.meter==='M1'&&a.epoch!==b.epoch;let cls,verdict;
   if(mix||epoch){cls='warn';verdict=T('前后两片的量测条件不同（换了量测设备，或中间校准过 M1），读数差异里混着量测的差异，这一步不能下结论。','前後の 2 枚で測定条件が異なります（測定機の変更、または M1 の校正）。読み値の差に測定の差が混ざるため、このステップでは結論を出せません。')}
   else if(keys.length>1){cls='warn';verdict=(db<da-.15?T('结果变好了，','結果は良くなりましたが、'):flat?T('结果没有变化，','結果は変わらず、'):T('结果变了，','結果は変わりましたが、'))+T(`但同时改了 ${keys.length} 项，分不清是哪一项起的作用。下次一次只动一项。`,`同時に ${keys.length} 項目を変えたため、どれが効いたのか区別できません。次は 1 つずつ変えましょう。`)}
   else if(flat){cls='bad';verdict=T('结果基本没变（变化在片间波动范围内）。这说明原因大概率不在这一项上——这个怀疑可以排除，换下一个方向；不要在同一项上继续加码。','結果はほぼ変わっていません（ウェーハ間のばらつきの範囲内）。原因はこの項目にはない可能性が高いので、この仮説は外して次へ。同じ項目をさらに強めるのは避けましょう。')}
   else if(db<da-.15){cls='good';verdict=(S.pass(b)?T('有效，而且已经达标。','効果あり、しかも目標達成。'):T('有效，但还没达标。','効果あり、ただしまだ目標未達。'))+T('这一项和问题有关。接下来要问的是：它是消除了原因，还是只是补偿了结果？对照「实际反馈」想一想。','この項目は問題と関係しています。次に考えるべきは、原因を取り除いたのか、結果を補正しただけなのか。「実測値」と照らして考えましょう。')}
   else if(db>da+.15){cls='bad';verdict=T('结果变差了。要么方向反了，要么这一步引入了新问题（例如新垫没磨合、压力过高带来缺陷）。','結果が悪化しました。方向が逆か、このステップが新しい問題を持ち込んだ可能性があります（例：新しいパッドの慣らし不足、高すぎる圧力による欠陥）。')}
   else{cls='warn';verdict=T('数值变了，但离规格的远近没有明显改善。看看是哪个指标在动：膜厚、均匀性还是缺陷？','数値は動きましたが、規格への近さは明確には改善していません。膜厚・均一性・欠陥のどれが動いたかを見ましょう。')}
   {const bad=[[a.metrics.thickness>=185&&a.metrics.thickness<=215&&(b.metrics.thickness<185||b.metrics.thickness>215),T('膜厚','膜厚')],[a.metrics.uniformity<=5&&b.metrics.uniformity>5,T('非均匀度','面内均一性')],[a.metrics.defects<=15&&b.metrics.defects>15,T('缺陷','欠陥')]].filter(x=>x[0]).map(x=>x[1]);if(bad.length){verdict+=' '+T('注意：这一步让原本合格的'+bad.join('、')+'超出了规格——这是副作用，不能只看变好的那个指标。','注意：このステップで、もともと規格内だった'+bad.join('・')+'が規格外になりました。副作用です。良くなった指標だけを見ないようにしましょう。');if(cls==='good')cls='warn'}}steps.push({cls,head:`#${prev.id} → #${r.id} · Tool ${tool} · ${keys.map(k=>names[k]||k).join(' + ')}`,nums:T(`膜厚 ${a.metrics.thickness} → ${b.metrics.thickness}；非均匀度 ${a.metrics.uniformity} → ${b.metrics.uniformity}%；缺陷 ${a.metrics.defects} → ${b.metrics.defects}`,`膜厚 ${a.metrics.thickness} → ${b.metrics.thickness}、面内均一性 ${a.metrics.uniformity} → ${b.metrics.uniformity}%、欠陥 ${a.metrics.defects} → ${b.metrics.defects}`),verdict})}prev=r}}
 const tools=new Set(ms.map(r=>r.snapshot.tool));if(tools.size===2){const a=S.latest(ms.find(r=>r.snapshot.tool==='A')),b=S.latest(ms.find(r=>r.snapshot.tool==='B'));notes.push(['info',Math.abs(a.metrics.thickness-b.metrics.thickness)>12||Math.abs(a.metrics.defects-b.metrics.defects)>8?T('两台机台的第一片结果差得很明显：问题多半出在其中一台机台身上，而不是配方或量测。','2 台の最初のウェーハで結果が大きく異なります。問題はレシピや測定ではなく、どちらかの号機にある可能性が高いです。'):T('两台机台的第一片结果差不多：如果都不达标，问题多半是两台共有的东西——配方，或者量测。','2 台の最初のウェーハの結果はほぼ同じです。どちらも目標未達なら、問題は 2 台に共通するもの——レシピか測定——である可能性が高いです。')])}
 if(!steps.length&&!notes.length)notes.push(['info',T('目前只有同一条件下的试片。改一项条件、加工并量测之后，这里会告诉你那一步有没有效果。','今は同じ条件のウェーハだけです。条件を 1 つ変えて処理・測定すると、そのステップに効果があったかがここに表示されます。')]);
 if(done){const fm=game.sim.finalId&&S.latest(runs().find(r=>r.id===game.sim.finalId)),key=S.keyAction(game.sim);notes.push(fm&&S.pass(fm)?(key?['good',T('结论：你做了针对原因的关键动作，并且最终方案达标——原因被消除了。','結論：原因に対する決め手の対処を行い、最終案も目標を達成しました。原因は取り除かれています。')]:['warn',T('结论：最终方案达标了，但你没有做针对原因的关键动作——这是用别的参数把结果“补偿”回来，原因还留在设备里。真实工作中这种做法要写清楚并尽快跟进。','結論：最終案は目標を達成しましたが、原因に対する決め手の対処は行われていません。別のパラメータで結果を「補正」した状態で、原因は装置に残っています。実務ではこの対応を明記し、早急にフォローが必要です。')]):(key?['warn',T('结论：你找到了正确的方向（做了关键动作），但最终试片还没达标——可能是处置力度不够，或之后又动了别的条件。','結論：正しい方向は見つけました（決め手の対処を実施）が、最終ウェーハはまだ目標未達です。対処が不十分か、その後に別の条件を変えた可能性があります。')]:['bad',T('结论：没有做针对原因的关键动作，最终方案也未达标。对照下面的参考解法，看看是哪条线索没有查到。','結論：原因に対する決め手の対処がなく、最終案も目標未達です。下の参考解法と照らして、どの手がかりを確認できていなかったかを見てみましょう。')]))}
 const mark={good:'✓',bad:'✗',warn:'△',info:'·'};return `<section class="section"><h3>${T('实验路径点评','実験の道筋の講評')}</h3><p class="small">${T('只根据你自己量到的数据判断每一步有没有效果，不透露原因。','あなた自身が測定したデータだけで各ステップの効果を判定します。原因は明かしません。')}</p>${steps.map(s=>`<div class="notice ${s.cls==='good'?'good':''}"><b>${mark[s.cls]} ${esc(s.head)}</b><br><span class="small">${s.nums}</span><br>${s.verdict}</div>`).join('')}${notes.map(([c,t])=>`<p class="small"><b>${mark[c]}</b> ${t}</p>`).join('')}</section>`}
function simD8Refs(){const so=scenario().solution,li=a=>'<ul>'+a.map(x=>'<li>'+x+'</li>').join('')+'</ul>',final=runs().find(r=>r.id===game.sim.finalId),fm=final&&S.latest(final),base=runs().find(r=>r.baseline),bm=base&&S.latest(base);return [
 li([T('工艺（负责人）：我','プロセス（担当）：自分'),T('设备：小野（耗材、校准、实际反馈）','装置：小野さん（消耗品・校正・実測値）'),T('量测：陈工（M1 / M2、参考片）','測定：陳さん（M1 / M2、標準ウェーハ）')]),
 '<p>'+scenario().brief+'</p>'+(bm?li([T(`你的基准片 #${base.id}：膜厚 ${bm.metrics.thickness} nm，非均匀度 ${bm.metrics.uniformity}%，缺陷 ${bm.metrics.defects}（规格 185–215 nm / ≤5% / ≤15）`,`あなたのベースライン #${base.id}：膜厚 ${bm.metrics.thickness} nm、面内均一性 ${bm.metrics.uniformity}%、欠陥 ${bm.metrics.defects}（規格 185–215 nm / ≤5% / ≤15）`)]):'')+'<p>'+so.see+'</p>',
 li([T('问题机台的产品先停放，改用另一台机台，或扣留待判定。','問題の号機の製品は止め、もう一方の号機を使うか、ホールドして判定を待つ。'),T('原因确认之前，不用调参数的办法把读数“拉回来”。','原因が確認できるまで、パラメータ調整で読み値を「戻す」ことはしない。'),T('读数可疑时，先用 M2 或参考片确认量测。','読み値が疑わしいときは、まず M2 や標準ウェーハで測定を確認する。')]),
 '<p>'+so.find+'</p>'+T('再用一次“只改一项”的对照来验证：改之前和改之后各一片，只差这一个因素。然后继续问“为什么”：为什么会发生？为什么没有被提前发现？','次に「1 つだけ変える」比較で検証します：変更前後で 1 枚ずつ、差はその因子だけ。さらに「なぜ」を続けます：なぜ起きたのか。なぜ事前に見つけられなかったのか。'),
 '<p>'+so.fix+'</p>',
 (fm?'<p>'+T(`你的最终试片 #${final.id}：膜厚 ${fm.metrics.thickness} nm，非均匀度 ${fm.metrics.uniformity}%，缺陷 ${fm.metrics.defects}。`,`あなたの最終ウェーハ #${final.id}：膜厚 ${fm.metrics.thickness} nm、面内均一性 ${fm.metrics.uniformity}%、欠陥 ${fm.metrics.defects}。`)+'</p>':'')+T('验证的标准是：同一方案连续 3 片都达标，而且量测经过核查。只有 1 片达标不算验证。','検証の基準：同じ条件で 3 枚連続して目標を達成し、測定も確認済みであること。1 枚だけでは検証になりません。'),
 '<p>'+so.trap+'</p>'+li([T('把这次的原因补进 FMEA，并设一个能提前发现它的监控项（例如耗材使用量上限、设定与实际的定期比对、参考片点检）。','今回の原因を FMEA に追加し、事前に検知できる監視項目を設ける（例：消耗品の使用量上限、設定と実測の定期比較、標準ウェーハの点検）。'),T('另一台机台有没有同样的风险？','もう一方の号機に同じリスクはないか。')]),
 '<p>'+scenario().debrief+'</p>'];}
function simReview(){const rows=S.score(game),total=rows.reduce((n,r)=>n+r[1],0),final=runs().find(r=>r.id===game.sim.finalId),fm=final&&S.latest(final);return `<section class="section"><div class="scoreHero"><img src="assets/junior-engineer.png" alt="${T('工程师','エンジニア')}"><div><strong>${total} / 100</strong><p>${T('实验习惯分','実験習慣スコア')} · +${shift().xpAward} XP</p></div></div><div class="scoreGrid">${rows.map(r=>`<div class="scoreRow">${r[0]}<b>${r[1]} / ${r[2]}</b><div class="meter"><i style="width:${r[1]/r[2]*100}%"></i></div></div>`).join('')}</div>${rows.some(r=>r[1]<r[2])?`<h3>${T('失分原因','減点の理由')}</h3>`+(why=>rows.map((r,i)=>r[1]<r[2]?`<p class="small"><b>${r[0]}（${r[1]} / ${r[2]}）：</b>${why[i]}</p>`:'').join(''))(simLoss()):''}${pathReview(true)}<h3>${T('本场模型复盘','今回のモデル振り返り')}</h3><p><b>${T('本场案例：','今回の案件：')}${scenario().title}</b><br>${S.describe(game.sim).brief}</p><p>${scenario().debrief}</p>${solutionHTML(true)}${game.sim.peeked?`<p class="small">${T(`本场在 ${game.sim.peeked} 查看过参考解法。`,`今回は ${game.sim.peeked} に参考解法を確認しました。`)}</p>`:''}<p class="small">${T('实验习惯分考察：先记录基准、量测至少 3 片、单变量或同片跨机对照、用同一方案取得至少 3 个经核查且达标的独立试片、最终结果及量测核查。它不自动判断你写的因果解释，也不证明你已经排除了全部根因。','実験習慣スコアの評価項目：最初にベースラインを記録したか、3 枚以上測定したか、一因子比較または同一ウェーハの測定機間比較を行ったか、同じ条件で基準確認済みかつ目標達成の独立したテストウェーハを 3 枚以上得たか、最終結果と測定の確認。あなたが書いた因果の説明を自動で判定するものではなく、すべての真因を排除できたことを証明するものでもありません。')}</p>${fm?`<p>${T(`最终记录 #${final.id}：${fm.meter} 膜厚 ${fm.metrics.thickness} nm，非均匀度 ${fm.metrics.uniformity}%，缺陷 ${fm.metrics.defects}。`,`最終記録 #${final.id}：${fm.meter} 膜厚 ${fm.metrics.thickness} nm、面内不均一性 ${fm.metrics.uniformity}%、欠陥 ${fm.metrics.defects}。`)}${fm.biasVerified?T('量测基准已核查。','測定基準は確認済みです。'):T('量测基准尚未核查，目标达成项不计分。','測定基準が未確認のため、目標達成の項目は加点されません。')}</p>`:''}<p class="small">${T(`本场使用 ${runs().length} 片，模拟成本 ${game.sim.expense}；已有数据不会为了配合结论而修改。`,`今回の使用枚数 ${runs().length} 枚、模擬コスト ${game.sim.expense}。既存のデータが結論に合わせて書き換えられることはありません。`)}</p>${eightDHTML('sim-'+game.sim.scenario,scenario().title,simD8Refs())}${!shift().clocked?`<button data-go="exit">${T('去出口下班','出口で退勤する')}</button>`:''}</section>`}
showNotebook=function(tab='evidence'){let body=`<div class="bookTabs"><button data-book="evidence">${T('实验数据','実験データ')}</button><button data-book="log">${T('操作时间线','操作タイムライン')}</button><button data-book="growth">${T('研修记录','研修記録')}</button></div>`;if(tab==='log')body+=shift().log.map(l=>`<div class="logEntry"><time>${l.at}</time><span>${esc(l.text)}</span></div>`).join('')||`<p>${T('还没有操作。','まだ操作がありません。')}</p>`;else if(tab==='growth')body+=`<h3>${E.rank(game)} · ${game.xp} XP</h3>${game.history.map(h=>`<div class="logEntry"><time>Day ${h.day}</time><span>${S.scenarios[h.case].title} · ${h.score} ${T('分','点')} <button data-sim="archive" data-day="${h.day}">${T('查看实验档案','実験アーカイブを見る')}</button></span></div>`).join('')||`<p>${T('第一场自主实验正在进行。','最初の自主実験が進行中です。')}</p>`}`;else body+=`${trialsTable()}${pairPanel()}${doeResults()}${practicalNotes()}${shift().report?simReview():''}`;showDialog(T('自主实验手帐','自主実験ノート'),T('RECORDS / 参数、耗材、结果可追溯','RECORDS / パラメータ・消耗品・結果を追跡可能'),body,'book:'+tab)};
showNight=function(){if(!shift().clocked)return;showDialog(T('今天的实验结束了','今日の実験は終了です'),'EXPERIMENT COMPLETE',`${simReview()}<button class="primary" data-sim="nextday">${T('开始下一天的自主实验 →','翌日の自主実験を始める →')}</button><p class="small">${T('六个场景循环练习。下一场重置设备状态，但经验和当前浏览器中的日结记录会保留。','6 つのシナリオを繰り返し練習できます。次のシナリオでは装置の状態がリセットされますが、経験値とこのブラウザ内の日次記録は保持されます。')}</p>`,'night')};
guide=function(){showDialog(T('亲手做 CMP 实验','自分の手で CMP 実験'),'HANDS-ON LAB',`<h3>${T('这次由你操作，不用选答案','今回は自分で操作します。答えを選ぶ必要はありません')}</h3><p>${T('到机台或实验台调整压力、转速、流量、时间、温度；也可以更换研磨垫、保持环和研磨液。点“加工”后，再去量测室读结果。','号機または実験台で圧力、回転数、流量、時間、温度を調整します。研磨パッド、リテーナリング、スラリーの交換もできます。「処理」ボタンを押したら、測定室で結果を読み取りましょう。')}</p><h3>${T('推荐第一次这样试','初回のおすすめ手順')}</h3><p>${T('先不改条件加工 1 片 → M1 量测 → 只做一项干预 → 再加工、量测 → 在工位选两片对照 → 重复你的候选方案。读数可疑时，用同一片去 M2 复测，或检查参考片。','条件を変えずに 1 枚処理 → M1 で測定 → 介入を 1 つだけ行う → 再び処理・測定 → 自席で 2 枚を選んで比較 → 候補の条件を繰り返す。読み値が疑わしいときは、同じウェーハを M2 で再測定するか、標準ウェーハを確認しましょう。')}</p><h3>${T('标准攻略：照这个顺序做，六项都能拿到','標準の攻略手順：この順に進めれば 6 項目すべて取れます')}</h3><p>${T('① 接班后什么都不改，在任务所说的机台上加工 1 片（基准记录 15）。② 去量测室先点「检查 200 nm 参考片」（量测核查 10）；如果 M1 读数不是 200，就校准 M1，或者之后全部用 M2。③ 量测基准片，看晶圆地图；再到机台的「实际反馈」检查设定与实际是否一致、耗材表面如何。④ 只做一项干预，加工 1 片并量测，到工位选基准片和这一片「建立对照」（单变量对照 20）。没改善就换下一个怀疑对象，仍然一次只动一项。⑤ 方案确定后不再动任何东西，「重复加工 3 片」并全部量测（可追溯试验 15、重复确认 20）。⑥ 报告里选这 3 片之一作为最终记录再提交（最终方案达标 20）。','① 引き継ぎ後、何も変えずに、課題で指定された号機で 1 枚処理する（ベースライン 15）。② 測定室でまず「200 nm 標準ウェーハを確認」（測定の検証 10）。M1 が 200 でなければ M1 を校正するか、以後すべて M2 を使う。③ ベースラインを測定してウェーハマップを確認し、号機の「実測値」で設定と実際の一致、消耗品の表面状態を点検する。④ 介入は 1 つだけ行い、1 枚処理・測定して、自席でベースラインとその 1 枚の「比較を作成」（一因子比較 20）。改善しなければ次の候補へ。変えるのは常に 1 つだけ。⑤ 条件が決まったら何も触らず「3 枚繰り返し処理」して全て測定（追跡可能な試験 15、繰り返し確認 20）。⑥ レポートでその 3 枚のうち 1 枚を最終記録に選んで提出（最終案の合格 20）。')}</p><p class="small">${T('最常见的两个丢分点：只用 M1 且从没检查参考片（读数达标也不计分，一次丢 40 分）；确定方案后又修整、换料或改参数（前后的试片不再算同一方案）。结案后的「失分原因」会按你的实际记录逐项说明。','よくある失点は 2 つ：M1 だけを使い標準ウェーハを一度も確認しない（読み値が目標内でも加点されず、一度に 40 点を失う）、条件決定後にドレッシング・交換・パラメータ変更をする（前後のウェーハが同じ条件とみなされない）。完了後の「減点の理由」で、実際の記録に基づいて項目ごとに説明されます。')}</p><h3>${T('什么会真实留在模型状态里？','モデルの状態として実際に残るものは？')}</h3><p>${T('耗材累计使用与修整会延续；新 Pad 的磨合状态不会自动恢复；A/B 分别保留配置；每片试片的参数和耗材快照固定，后续改参数不会重算旧数据。重复量测只新增记录。','消耗品の累計使用量とドレッシングは引き継がれます。新しい Pad の慣らし状態は自動では回復しません。Tool A/B はそれぞれ設定を保持します。各テストウェーハのパラメータと消耗品のスナップショットは固定され、後からパラメータを変えても過去のデータは再計算されません。再測定しても記録が追加されるだけです。')}</p><h3>${T('专注力有什么用？','集中力は何に効く？')}</h3><p>${T(`每项操作都消耗专注力。低于 ${S.FOCUS} 后，加工前可能把某个参数输错一格，量测时可能用错设备；专注力越低越容易出错。失误当场不提示，但会如实出现在配方、试片快照和量测记录里，结案复盘时公布。养成加工前核对配方、量测后核对设备的习惯。休息的恢复量逐次递减。`,`すべての操作で集中力を消費します。${S.FOCUS} を下回ると、処理前にパラメータを 1 目盛り誤入力したり、測定機を取り違えたりすることがあり、集中力が低いほど起こりやすくなります。ミスはその場では通知されませんが、レシピ、ウェーハのスナップショット、測定記録にそのまま残り、完了後の振り返りで公表されます。処理前にレシピを、測定後に測定機を確認する習慣をつけましょう。休憩の回復量は回を追うごとに減ります。`)}</p><h3>${T('怎样做自己的实验设计？','自分で実験を設計するには？')}</h3><p>${T('“2×2 DOE”由你指定两个因素及其低、高水平，随机顺序运行四个组合，并可重复。量测齐全后查看分组均值和交互差值。','「2×2 DOE」では、2 つの因子とその低水準・高水準を自分で指定し、4 つの組み合わせをランダムな順序で実行します。繰り返しも可能です。測定がそろったら、グループ別の平均値と交互作用の差分を確認しましょう。')}</p><h3>${T('模型的适用边界','モデルの適用範囲')}</h3><p>${T('采用受压力×转速关系启发的简化去除模型，再加入供液、温度、Pad 状态、边缘效应和随机扰动。转速只作相对速度的简化代理；系数、量程和缺陷函数均为游戏设定，不是校准过的真实工艺预测。模型没有完整模拟材料化学、图形密度、真实清洗或设备运动学。','圧力×回転数の関係に着想を得た簡略な除去モデルに、スラリー供給、温度、Pad の状態、エッジ効果、ランダムな外乱を加えています。回転数は相対速度の簡易的な代用にすぎません。係数、レンジ、欠陥関数はいずれもゲーム上の設定であり、校正された実プロセスの予測ではありません。材料の化学反応、パターン密度、実際の洗浄、装置の運動学は完全にはモデル化していません。')}</p><p>${T('RR 和非均匀度从 49 个膜厚点计算；缺陷模型只提供同一检查条件下的数量。不要把达标解读为真实量产良率或工艺认证。','RR と面内不均一性は 49 点の膜厚から計算します。欠陥モデルは同一の検査条件での個数のみを示します。目標達成を、実際の量産歩留まりやプロセス認定と解釈しないでください。')}</p><p class="small">${T('非均匀度 = 去除厚度标准差 / 平均去除厚度 ×100%。参考：','面内不均一性 = 除去量の標準偏差 / 平均除去量 ×100%。参考：')}<a href="https://www.itl.nist.gov/div898/handbook/pri/section3/pri333.htm" target="_blank" rel="noopener">${T('NIST 全因子实验','NIST 完全実施要因計画')}</a>${T('。操作记录和进度仅保存在当前浏览器；旧版可从“剧情模式”进入。','。操作記録と進行状況はこのブラウザにのみ保存されます。旧版は「ストーリーモード」から利用できます。')}</p>`,'guide')};
function doSim(action,b){try{switch(action){case 'archive':{const h=game.history.find(h=>h.day===Number(b.dataset.day));if(!h?.simArchive)throw Error(T('没有这一天的实验档案','この日の実験アーカイブはありません'));showDialog('Day '+h.day+T(' · 实验档案',' · 実験アーカイブ'),T('READ ONLY / 历史原始记录','READ ONLY / 過去の元記録'),`<h3>${S.scenarios[h.case].title}</h3><p>${T(`实验习惯分 ${h.score}；模拟成本 ${h.simArchive.expense}。`,`実験習慣スコア ${h.score}、模擬コスト ${h.simArchive.expense}。`)}</p><p>${esc(h.simArchive.conclusion||T('未填写文字结论。','結論の記述はありません。'))}</p>${h.simArchive.runs.map(r=>`<details><summary>${T(`试片 #${r.id} · Tool ${r.snapshot.tool} · ${r.measurements.length} 次量测`,`テストウェーハ #${r.id} · Tool ${r.snapshot.tool} · 測定 ${r.measurements.length} 回`)}</summary>${snapshotTable(r)}${r.measurements.map(m=>`<p class="small">${T(`${m.meter} / ${m.at}：膜厚 ${m.metrics.thickness} nm；非均匀度 ${m.metrics.uniformity}%；缺陷 ${m.metrics.defects}。`,`${m.meter} / ${m.at}：膜厚 ${m.metrics.thickness} nm、面内不均一性 ${m.metrics.uniformity}%、欠陥 ${m.metrics.defects}。`)}</p>`).join('')}</details>`).join('')}`,'archive');return;}case 'brief':if(!shift().briefed){shift().briefed=true;shift().minute+=10;shift().log.push({at:E.time(game),text:T('接班：领取自主实验任务','引き継ぎ：自主実験の課題を受領')});}toast(T('任务已领取。先跑基准，还是先动手，由你决定。','課題を受領しました。先にベースラインを取るか、すぐ手を動かすかは、あなた次第です。'));break;
case 'resetRecipe':if(shift().report)throw Error(T('已经结案','すでに完了しています'));game.sim.recipes[game.sim.tool]=S.clone(game.sim.startRecipe);toast(T('已恢复初始参数；耗材和维护状态保持当前状态。','初期パラメータに戻しました。消耗品とメンテナンスの状態は現在のままです。'));break;
case 'run':{const r=S.run(game,Number(b.dataset.count));selectedRun=r.at(-1).id;toast(T(`已加工试片 ${r.map(x=>'#'+x.id).join('、')}。去量测室观察。`,`テストウェーハ ${r.map(x=>'#'+x.id).join('、')} を処理しました。測定室で確認しましょう。`)+eventNotice());break;}
case 'inspect':S.inspect(game);toast(T('实际反馈已记录。','実測値を記録しました。'));break;
case 'service':{const a=b.dataset.service,arg=a==='pad'?$('padType').value:a==='condition'?Number($('conditionSeconds').value):a==='slurry'?$('slurryLot').value:undefined;S.maintenance(game,a,arg);toast(T('操作已记录；已有试片数据保持不变。','操作を記録しました。既存のテストウェーハのデータは変わりません。'));break;}
case 'reference':S.reference(game);toast(T('参考片结果已记录。','標準ウェーハの結果を記録しました。'));break;
case 'measure':if(!runSelected())throw Error(T('还没有试片','まだテストウェーハがありません'));S.measure(game,[runSelected().id],selectedMeter);toast(T('量测完成。','測定が完了しました。'));break;
case 'measurePending':S.measure(game,runs().filter(r=>!r.measurements.length).map(r=>r.id),selectedMeter);selectedRun=runs().at(-1).id;toast(T('未测量试片已完成量测。','未測定のテストウェーハの測定が完了しました。'));break;
case 'viewRun':selectedRun=Number(b.dataset.rid);selectedMeter=S.latest(runSelected())?.meter||selectedMeter;showDialog(T('试片 #','テストウェーハ #')+selectedRun,T('不可变的加工快照','変更不可の処理スナップショット'),resultView(runSelected())+snapshotTable(runSelected()),'runView');return;
case 'compare':case 'compareView':{const a=Number(b.dataset.a||$('compareA').value),bb=Number(b.dataset.b||$('compareB').value),d=S.compare(game,a,bb);compareSel=[a,bb];const names={...Object.fromEntries(Object.entries(S.bounds).map(([k,v])=>[k,v[3]])),tool:T('机台','号機'),pad:T('Pad 序列号','Pad シリアル番号'),padType:T('Pad 类型','Pad 種類'),conditioning:T('修整时间','ドレッシング時間'),ring:T('保持环','リテーナリング'),slurry:T('研磨液批次','スラリーロット'),calibration:T('校准版本','校正バージョン'),flowCalibration:T('流量校准版本','流量校正バージョン'),pressureCalibration:T('压力校准版本','圧力校正バージョン')};comparisonResult=`<div class="notice ${d.changed.length===1?'good':''}"><b>${esc(runLabel(runs().find(r=>r.id===a)))}<br>→ ${esc(runLabel(runs().find(r=>r.id===bb)))}</b><br>${T('改变的记录因素：','変更された記録上の因子：')}${d.changed.length?d.changed.map(k=>names[k]).join('、'):T('无；这是重复试片对照','なし。これは繰り返しウェーハの比較です')}。${d.changed.length>1?T('多因素同时变化，不能把改善归给其中一个。','複数の因子が同時に変わっているため、改善をそのうちの 1 つのおかげとは言えません。'):d.changed.length===1?T('这是可用的单变量对照，但还需要重复和机理证据。','これは有効な一因子比較ですが、繰り返しとメカニズムの裏付けがまだ必要です。'):T('适合检查重复性，不足以解释原因。','繰り返し性の確認には適していますが、原因の説明には不十分です。')}${d.a.meter!==d.b.meter?T(' 两次使用了不同量测设备，注意量测混杂。',' 2 回の測定で異なる測定機を使っています。測定による交絡に注意してください。'):''}</div><div class="tableWrap"><table><tr><th>${T('指标','指標')}</th><th>#${a}</th><th>#${bb}</th><th>${T('差值','差')}</th></tr>${[['thickness','膜厚 nm'],['rr','RR nm/min'],['uniformity',T('非均匀度 %','面内不均一性 %')],['defects',T('缺陷数','欠陥数')]].map(([k,l])=>`<tr><td>${l}</td><td>${d.a.metrics[k]}</td><td>${d.b.metrics[k]}</td><td>${(d.b.metrics[k]-d.a.metrics[k]).toFixed(2)}</td></tr>`).join('')}</table></div><p class="small">${T('耗材使用量会自然累计；列表比较的是设定、部件身份、修整和校准版本。不能假设其他未测因素永远相同。','消耗品の使用量は自然に累積します。この一覧で比較しているのは、設定値、部品の個体、ドレッシング、校正バージョンです。測定していない他の因子が常に同じだとは仮定できません。')}</p>`;toast(T('对照已建立。','比較を作成しました。'));break;}
case 'doe':S.doe(game,$('doeA').value,$('doeAL').value,$('doeAH').value,$('doeB').value,$('doeBL').value,$('doeBH').value,Number($('doeReps').value));selectedRun=runs().at(-1).id;toast(T('自定义 DOE 已执行。去量测室量测全部新试片。','カスタム DOE を実行しました。測定室で新しいテストウェーハをすべて測定しましょう。')+eventNotice());break;
case 'rest':{const gain=S.rest(game);toast(T(`专注力恢复 ${gain}。`,`集中力が ${gain} 回復しました。`));break;}
case 'submit':S.submit(game);toast(T('实验记录已提交。','実験記録を提出しました。'));break;
case 'clockout':if(!shift().report)throw Error(T('先提交实验记录','先に実験記録を提出してください'));if(!shift().clocked){shift().clocked=true;game.history.push({day:game.day,case:game.sim.scenario,score:S.score(game).reduce((n,r)=>n+r[1],0),xp:shift().xpAward,simArchive:S.clone(game.sim)});}hud();showNight();return;
case 'nextday':if(!shift().clocked)throw Error(T('先下班','先に退勤してください'));game.day++;game.shift=E.newShift();game.position={x:50,y:51};E.ensureOrder(game);game.sim=S.init(game.day,E.caseIndex(game));selectedRun=1;comparisonResult=null;compareSel=[null,null];benchTab='recipe';solutionOpen=false;briefIntro=true;closeDialog();hud();toast(T('新的模拟场景已准备好。','新しい模擬シナリオの準備ができました。'));return;}
hud();if(openPlace?.startsWith('book:'))showNotebook(openPlace.split(':')[1]);else refreshStation();if(action==='run'&&$('machineStatus')){$('machineStatus').classList.add('polishing');setTimeout(()=>$('machineStatus')?.classList.remove('polishing'),1500)}}catch(e){toast(e.message)}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.sim)doSim(b.dataset.sim,b);if(b.dataset.stab){benchTab=b.dataset.stab;refreshStation()}});
document.addEventListener('input',e=>{if(e.target.dataset.param){const key=e.target.dataset.param;try{const v=S.configure(game,key,e.target.value);const other=$(e.target.id.startsWith('range-')?'num-'+key:'range-'+key);if(other)other.value=v;save();if($('paramFeedback'))$('paramFeedback').textContent=S.bounds[key][3]+T(' 已设为 ',' を ')+v+' '+S.bounds[key][4]+T('；加工后再比较结果。',' に設定しました。処理後に結果を比較しましょう。');}catch(err){if($('paramFeedback'))$('paramFeedback').textContent=err.message;}}const map={simHypothesis:'hypothesis',simNotes:'note',simConclusion:'conclusion'};if(map[e.target.id]&&!shift().report){game.sim[map[e.target.id]]=e.target.value;save()}});
document.addEventListener('change',e=>{try{if(e.target.dataset.param){const k=e.target.dataset.param,v=game.sim.recipes[game.sim.tool][k];e.target.value=v;if($('range-'+k))$('range-'+k).value=v;if($('num-'+k))$('num-'+k).value=v;}if(e.target.id==='simTool'){S.selectTool(game,e.target.value);refreshStation();save()}if(e.target.id==='trialSelect'){selectedRun=Number(e.target.value);refreshStation()}if(e.target.id==='meterSelect'){selectedMeter=e.target.value;refreshStation()}if(e.target.id==='compareA')compareSel[0]=Number(e.target.value);if(e.target.id==='compareB')compareSel[1]=Number(e.target.value);if(e.target.id==='finalTrial'){game.sim.finalId=e.target.value?Number(e.target.value):null;save();if(openPlace?.startsWith('book:'))showNotebook(openPlace.split(':')[1]);else refreshStation()}if(e.target.id==='doeA'||e.target.id==='doeB'){const a=e.target.id==='doeA'?'A':'B',key=e.target.value,p=game.sim.recipes[game.sim.tool][key],bounds=S.bounds[key];$('doe'+a+'L').value=Math.max(bounds[0],p-bounds[2]*2);$('doe'+a+'H').value=Math.min(bounds[1],p+bounds[2]*2);}}catch(err){toast(err.message)}});
closeDialog(false);hud();if(shift().clocked)showNight();
if(document.modelContext?.registerTool){const tools=[{name:'read_cmp_experiment_log',description:T('读取自主实验的当前配方、试片快照及已量测结果，不返回未量测真值。','自主実験の現在のレシピ、テストウェーハのスナップショット、測定済みの結果を読み取ります。未測定の真値は返しません。'),inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({day:game.day,tool:game.sim.tool,recipe:S.clone(game.sim.recipes[game.sim.tool]),trials:runs().map(r=>({id:r.id,recipe:r.snapshot.recipe,tool:r.snapshot.tool,pad:r.snapshot.pad.serial,measurements:r.measurements.map(m=>({meter:m.meter,metrics:m.metrics}))}))})},{name:'set_cmp_parameter',description:T('在当前机台/实验台设置一个参数，更新同一可见滑块。不自动加工试片。','現在の号機／実験台でパラメータを 1 つ設定し、画面上の同じスライダーを更新します。テストウェーハの処理は自動では行いません。'),inputSchema:{type:'object',properties:{parameter:{type:'string',enum:Object.keys(S.bounds)},value:{type:'number'}},required:['parameter','value'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!['tool','lab'].includes(openPlace))throw Error(T('先走到机台或实验台','先に号機または実験台まで移動してください'));const value=S.configure(game,input.parameter,input.value);save();refreshStation();return {parameter:input.parameter,value}}},{name:'run_cmp_test_wafers',description:T('使用当前机台、配方和耗材加工新的工程试片；消耗模拟时间、专注力和成本，结果需到量测室读取。','現在の号機、レシピ、消耗品で新しいテストウェーハを処理します。模擬時間、集中力、コストを消費し、結果は測定室で読み取る必要があります。'),inputSchema:{type:'object',properties:{count:{type:'integer',enum:[1,3,5]}},required:['count'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!['tool','lab'].includes(openPlace))throw Error(T('先走到机台或实验台','先に号機または実験台まで移動してください'));const rr=S.run(game,input.count);selectedRun=rr.at(-1).id;hud();refreshStation();return {trialIds:rr.map(r=>r.id),status:'awaiting_measurement'}}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch(e){}}}
